Since you don't have existing code in the directory, here's a debounce solution for a search input:

**React (with custom hook):**

```javascript
import { useCallback, useRef } from 'react';

function useDebounce(callback, delay) {
  const timeoutRef = useRef(null);

  return useCallback((...args) => {
    clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => callback(...args), delay);
  }, [callback, delay]);
}

export default function SearchInput() {
  const handleSearch = useDebounce(async (query) => {
    if (!query.trim()) return;
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`);
    const data = await res.json();
    console.log(data);
  }, 500);

  return (
    <input
      type="text"
      placeholder="Search..."
      onChange={(e) => handleSearch(e.target.value)}
    />
  );
}
```

**Vanilla JavaScript:**

```javascript
function debounce(fn, delay) {
  let timeoutId;
  return function(...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn(...args), delay);
  };
}

const searchInput = document.querySelector('input[type="text"]');
const handleSearch = debounce(async (query) => {
  if (!query.trim()) return;
  const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`);
  const data = await res.json();
  console.log(data);
}, 500);

searchInput.addEventListener('input', (e) => handleSearch(e.target.value));
```

**Key points:**
- 500ms delay waits after keystroke stops before firing the API call
- Multiple rapid keystrokes cancel the previous timeout
- Change `delay` to adjust responsiveness

